请对以下 case 进行三维加权评分。

=== case_id ===
Case-17-queue-330

=== 用户原始指令 (query.txt) ===
帮我整个排号卡，主体是图，点开能导航去店里，看到叫到号

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "帮我整个排号卡，主体是图，点开能导航去店里，看到叫到号",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.maps",
        "abilityName": "com.huawei.hmos.maps.MainAbility",
        "uri": "geo:0,0?q=%E6%98%9F%E6%B2%B3%E8%8C%B6%E9%A4%90%E5%8E%85"
      }
    }
  ],
  "dataModel": {
    "value": {
      "queue": {
        "title": "排号叫号",
        "storeName": "星河茶餐厅",
        "calledLabel": "叫到",
        "calledNo": "A016",
        "actionText": "导航"
      },
      "assets": {
        "queueIllustration": "resources/base/media/queue_counter.png"
      }
    }
  },
  "assetCandidates": [
    {
      "assetRef": "queueIllustration",
      "src": "resources/base/media/queue_counter.png",
      "use": "queue card main illustration",
      "description": "排队取号柜台插图素材，用作排号卡主体视觉。",
      "bindTo": "/assets/queueIllustration",
      "static": true
    }
  ]
}

